"""Author the closed native cancellation image packer; no product Python dependency."""
from pathlib import Path
import struct
from hepta.hia_agent_assembly import render_assembly
from tools.generate_hia_multiversion_future import document
ROOT=Path(__file__).resolve().parents[1]
ROLES=('public','handles','effects','kernel')
MAGIC=int.from_bytes(b'HIAPCPK1','little')
BRIDGE=bytes.fromhex('')
HOLES={'public':197,'handles':554,'effects':367,'kernel':1045}

def reference_image(flats):
    if len(flats)!=4 or any(not f or len(f)>4194304 for f in flats):
        raise ValueError('four bounded actual HIA roles required')
    raw=bytearray(BRIDGE)
    for role,body in zip(ROLES,flats,strict=True):
        hole=HOLES[role]
        struct.pack_into('<i',raw,hole,len(raw)-hole-4)
        raw.extend(body)
    return bytes(raw)

def source_program():
    source=f'''
def pack(s:readbuf,o:mutbuf,w:mutbuf) -> u32:
    if length(s)<64 or word_load(s,0)!={MAGIC} or word_load(s,8)!=4:
        return 4294967293
    if word_load(s,48)!=0 or word_load(s,56)!=0:
        return 4294967293
    total=64
    i=0
    while i<4:
        n=word_load(s,16+i*8)
        if n==0 or n>4194304:
            return 4294967293
        total=total+n
        i=i+1
    if length(s)!=total or length(o)<total-64+{len(BRIDGE)}:
        return 4294967293
    prefix(o)
    at={len(BRIDGE)}
'''
    for index,role in enumerate(ROLES):
        hole=HOLES[role]
        source+=f'    word32(o,{hole},at-{hole+4})\n    at=at+word_load(s,{16+index*8})\n'
    source+=f'''    copy_bytes(s,o,64,{len(BRIDGE)},total-64)
    return total-64+{len(BRIDGE)}

def prefix(o:mutbuf) -> u64:
'''
    for i in range(0,len(BRIDGE),8):
        source+=f'    word(o,{i},{int.from_bytes(BRIDGE[i:i+8],"little")})\n'
    source+='''    return 0

def word(o:mutbuf,at:u64,value:u64) -> u64:
    i=0
    while i<8:
        store(o,at+i,(value>>(i*8))&255)
        i=i+1
    return 0

def word32(o:mutbuf,at:u64,value:u64) -> u64:
    i=0
    while i<4:
        store(o,at+i,(value>>(i*8))&255)
        i=i+1
    return 0

def copy_bytes(s:readbuf,o:mutbuf,at:u64,to:u64,n:u64) -> u64:
    i=0
    while i<n:
        store(o,to+i,byte(s,at+i))
        i=i+1
    return 0
'''
    return source

def main():
    doc=document(source_program(),'publication_cancellation_packer')
    path=ROOT/'examples/hia_bootstrap/publication_cancellation_packer.hepta'
    path.write_text(render_assembly(doc))
    print(path.name,path.stat().st_size)

if __name__=='__main__':
    main()
